python
def fixedPanelsPeakTicket(readings, k):
    a=readings
    out=[]
    s=0
    for i,x in enumerate(a):
        s+=x
        if i>=k: s-=a[i-k]
        if i>=k-1: out.append(s)
    return max(out,default=0)


java
class Solution {
  public int fixedPanelsPeakTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int s=0;for(int i=0;i<a.length;i++){s+=a[i];if(i>=k)s-=a[i-k];if(i>=k-1)out.add(s);}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
